  pay_no         varchar(64)   NOT NULL COMMENT '支付单号',
  pay_type       tinyint       NOT NULL DEFAULT 1 COMMENT '支付方式：1 模拟，2 微信支付',
  amount         decimal(10,2) NOT NULL COMMENT '支付金额',
