  deleted      tinyint       NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 正常，1 删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_refund_no (refund_no),
  KEY idx_order_id (order_id),
