-- 34. 定制需求表
CREATE TABLE IF NOT EXISTS custom_requirement (
  id            bigint        NOT NULL AUTO_INCREMENT COMMENT '主键',
  requirement_no varchar(32)  NOT NULL COMMENT '需求单号',
  customer_id   bigint        DEFAULT NULL COMMENT '客户 ID',
  contact_name  varchar(50)   NOT NULL COMMENT '联系人',
  contact_phone varchar(128)  NOT NULL COMMENT '联系电话（AES 密文）',
  destination   varchar(100)  NOT NULL COMMENT '目的地',
  depart_date   date          DEFAULT NULL COMMENT '期望出发日期',
  days          int           DEFAULT NULL COMMENT '天数',
  people_count  int           DEFAULT NULL COMMENT '人数',
  budget        decimal(10,2) DEFAULT NULL COMMENT '预算',
  preferences   text          DEFAULT NULL COMMENT '偏好说明',
  status        tinyint       NOT NULL DEFAULT 0 COMMENT '状态：0 待跟进，1 已报价，2 已成交，3 已关闭',
  handler_id    bigint        DEFAULT NULL COMMENT '跟进人 ID',
  remark        varchar(255)  DEFAULT NULL COMMENT '备注',
  version       int           NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
  create_by     bigint        DEFAULT NULL COMMENT '创建人 ID',
  create_time   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_by     bigint        DEFAULT NULL COMMENT '更新人 ID',
  update_time   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  deleted       tinyint       NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 正常，1 删除',
  PRIMARY KEY (id),
  UNIQUE KEY uk_requirement_no (requirement_no),
  KEY idx_customer_id (customer_id),
  KEY idx_status (status),
  KEY idx_handler_id (handler_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='定制需求表';

-- 35. 定制报价表（追加型）
CREATE TABLE IF NOT EXISTS custom_quote (
  id             bigint        NOT NULL AUTO_INCREMENT COMMENT '主键',
  requirement_id bigint        NOT NULL COMMENT '需求单 ID',
  quote_no       varchar(32)   NOT NULL COMMENT '报价单号',
  amount         decimal(10,2) NOT NULL COMMENT '报价金额',
  detail         text          DEFAULT NULL COMMENT '报价明细',
  valid_until    date          DEFAULT NULL COMMENT '有效期至',
  status         tinyint       NOT NULL DEFAULT 0 COMMENT '状态：0 待确认，1 已采纳，2 已失效',
  create_by      bigint        DEFAULT NULL COMMENT '创建人 ID',
  create_time    datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_quote_no (quote_no),
  KEY idx_requirement_id (requirement_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='定制报价表';

-- =============================================================================
-- 七、统计域（1 张）
-- =============================================================================

-- 36. 每日经营统计表
CREATE TABLE IF NOT EXISTS stat_daily (
  id                 bigint        NOT NULL AUTO_INCREMENT COMMENT '主键',
  stat_date          date          NOT NULL COMMENT '统计日期',
  order_count        int           NOT NULL DEFAULT 0 COMMENT '订单数',
  paid_order_count   int           NOT NULL DEFAULT 0 COMMENT '已支付订单数',
  sales_amount       decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '销售额',
  refund_amount      decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  new_customer_count int           NOT NULL DEFAULT 0 COMMENT '新增客户数',
  create_time        datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time        datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_stat_date (stat_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='每日经营统计表';

-- =============================================================================
-- 结构脚本结束：1 个数据库 routego、36 张业务表、1 张 undo_log 基础表
-- 初始化数据（管理员、角色、菜单、字典）见方案书 7.5，可整理为 data.sql
-- =============================================================================
-- =============================================================================
-- RouteGo 后台权限数据 · 标准初始化脚本（幂等）
-- 执行顺序：sql/admin-reset.sql → sql/admin-init.sql → 清 Redis admin:* 缓存
--
-- 本脚本写入：
--   1. 8 个内置角色（含「超级管理员」「系统管理员」）
--   2. 195 个接口级权限点，全部带中文说明（sys_permission.description）
--      覆盖 6 个域：admin 74 + catalog 40 + trade 23 + customer 26 + operations 32
--   3. 30 个菜单：5 个目录 + 25 个页面
--      系统管理 10 页、线路管理 5 页、订单管理 3 页、会员管理 3 页、运营中心 4 页
--   4. 角色 ↔ 菜单、角色 ↔ 权限点 的授权关系
--   5. 内置超级管理员账号：taishangxue520 / 12345678Ss
--      手机号 18807420597，邮箱 2120387318@qq.com
--   6. 10 类常用字典（33 个字典项）、8 条系统参数、3 条公告
--
-- 说明：
--   * 权限点 ID 1~195、菜单 ID 100~199 由本脚本固定占用，重跑会先删除再重建，
--     保证与后端 @SaCheckPermission 完全一致；用户自行新增的权限点（ID > 195）
--     不会被删除。
--   * 角色授权为「覆盖式」：重跑会把种子角色的授权恢复成脚本里的定义。
--   * 正式环境请在首次登录后立即修改内置账号密码。
-- =============================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------
-- 1. 内置角色（共 5 个）
--    sort 越小越靠前；super_admin / admin 为受保护角色（代码中不可停用、不可删除）。
--    普通用户 / 会员用户是 App 端角色：注册默认绑定普通用户，不分配后台菜单与权限点。
-- ---------------------------------------------------------------------------
INSERT INTO sys_role (id, role_name, role_code, sort, status, remark, version, deleted)
VALUES (1, '超级管理员', 'super_admin', 1, 1,
        '平台最高权限，鉴权时直接返回通配权限 *，拥有全部菜单，不可删除', 0, 0),
       (2, '系统管理员', 'admin', 10, 1,
        '维护账号、角色、字典、参数、公告、文件与日志；不含权限点与菜单结构的增删改', 0, 0),
       (3, '客服', 'support', 20, 1,
        '处理工单、定制需求与订单客诉，可查用户资料与线路信息', 0, 0),
       (4, '普通用户', 'normal_user', 90, 1,
        '注册用户默认角色（App 端），不分配后台菜单与权限点', 0, 0),
       (5, '会员用户', 'member_user', 91, 1,
        '付费会员角色，预留会员体系扩展', 0, 0)
ON DUPLICATE KEY UPDATE role_name = VALUES(role_name),
                        role_code = VALUES(role_code),
                        sort      = VALUES(sort),
                        status    = 1,
                        remark    = VALUES(remark),
                        deleted   = 0;

-- 历史遗留角色（系统运维/安全审计员/内容运营/数据分析师/只读访客等）清理
DELETE FROM sys_role_menu WHERE role_id > 5;
DELETE FROM sys_role_permission WHERE role_id > 5;
DELETE FROM sys_user_role WHERE role_id > 5;
DELETE FROM sys_role WHERE id > 5;

-- ---------------------------------------------------------------------------
-- 2. 权限点
--    命名规则：admin:<Controller>:<method>，必须与 Controller 上的 @SaCheckPermission 一致。
--    module 用于前端按模块分组与筛选，description 是该权限点的中文说明。
-- ---------------------------------------------------------------------------
-- 先清理种子区间（1~195）及其角色关联，保证权限码随代码同步
DELETE FROM sys_role_permission WHERE permission_id BETWEEN 1 AND 195;
DELETE FROM sys_permission WHERE id BETWEEN 1 AND 195;

